const update = $input.first().json;

let chatId, from, text, callbackData;

if (update.callback_query) {
  chatId       = update.callback_query.message.chat.id;
  from         = update.callback_query.from.first_name || 'User';
  callbackData = update.callback_query.data;
  text         = callbackData;
} else if (update.message) {
  chatId       = update.message.chat.id;
  from         = update.message.from.first_name || 'User';
  text         = update.message.text || '';
  callbackData = null;
}

const t = (text || '').toLowerCase().trim();

let action = 'unknown';

if (t === '/start' || t === '/menu' || t === 'menu' || callbackData === 'back_main') {
  action = 'main_menu';
} else if (callbackData === 'menu_marketing') {
  action = 'menu_marketing';
} else if (callbackData === 'menu_engagement') {
  action = 'menu_engagement';
} else if (callbackData === 'menu_analytics') {
  action = 'menu_analytics';
} else if (callbackData === 'menu_growth') {
  action = 'menu_growth';
} else if (callbackData === 'menu_status' || t === '/status') {
  action = 'menu_status';
} else if (callbackData && callbackData.startsWith('run_')) {
  action = callbackData;
}

return [{ json: { chatId, from, text, callbackData, action } }];

